const req = $('Notify Webhook').first().json.body;
const guardian = $('Fetch Guardian').first().json[0];
const p = req.payload || {};
const naira = (n) => '\u20a6' + Number(n || 0).toLocaleString('en-NG');
const brand = `\n  <div style=\"font-family:Georgia,serif;max-width:560px;margin:0 auto;border:1px solid #d9d2c3;border-radius:12px;overflow:hidden\">\n    <div style=\"background:#0a1830;color:#faf7ef;padding:24px 28px\">\n      <div style=\"font-size:20px\">${p.schoolName || "Archangels' Schools"}</div>\n      <div style=\"color:#e6c780;font-size:11px;letter-spacing:2px;text-transform:uppercase\">Dedicated to Excellence</div>\n    </div>\n    <div style=\"padding:28px;background:#fffdf8;color:#191510;font-family:Arial,sans-serif;font-size:14px;line-height:1.6\">{{BODY}}</div>\n    <div style=\"padding:14px 28px;background:#faf7ef;color:#8b8272;font-size:11px\">Powered by Nalto \u00b7 NALTO SchoolOS</div>\n  </div>`;
let subject, body;
switch (req.template) {
  case 'payment_receipt':
    subject = 'Fee Payment Confirmed \u2014 ' + (p.schoolName || "Archangels' Schools");
    body = `<p>Dear ${guardian.full_name},</p><p>We have received your payment of <strong>${naira(p.amount)}</strong> for <strong>${p.studentName}</strong> (${p.term}).</p><p>Receipt No: <strong>${p.receiptNumber}</strong></p><p>Thank you for your promptness. God bless you.</p>`;
    break;
  case 'invoice_issued':
    subject = 'Fee Invoice \u2014 ' + (p.term || 'Term 3 2025/2026');
    body = `<p>Dear ${guardian.full_name},</p><p>The fee invoice for <strong>${p.studentName}</strong> (${p.term}) is now available on the Parent Portal.</p><p>Total due: <strong>${naira(p.amount)}</strong>${p.dueDate ? ' \u00b7 Due by <strong>' + p.dueDate + '</strong>' : ''}.</p><p>Kindly log in to view the breakdown and pay securely online.</p>`;
    break;
  case 'owing_reminder':
    subject = 'Reminder: Outstanding Fees \u2014 ' + (p.schoolName || "Archangels' Schools");
    body = `<p>Dear ${guardian.full_name},</p><p>This is a gentle reminder that <strong>${p.studentName}</strong> has an outstanding balance of <strong>${naira(p.amount)}</strong> for ${p.term}.</p><p>Kindly settle the balance on the Parent Portal to keep your child's record in good standing.</p>`;
    break;
  default:
    subject = p.subject || 'Notification \u2014 ' + (p.schoolName || "Archangels' Schools");
    body = `<p>Dear ${guardian.full_name},</p><p>${p.message || ''}</p>`;
}
return [{ json: {
  to: guardian.email,
  subject,
  html: brand.replace('{{BODY}}', body),
  guardian_id: guardian.id,
  template_key: req.template,
  channel: 'email',
  payload: p
} }];

// WhatsApp branch — no-op for now; production swaps in Twilio/WhatsApp Cloud API.
const req = $('Notify Webhook').first().json.body;
const guardian = $('Fetch Guardian').first().json[0];
return [{ json: {
  guardian_id: guardian.id,
  template_key: req.template,
  channel: 'whatsapp',
  status: 'queued',
  payload: req.payload || {}
} }];

